import {fairTestPage,bindFairTest} from './fair-test-ui.mjs';
import {questionCases,questionSource} from './question-bench-content.mjs';
import {newQuestionWork,questionText,questionLength,changeQuestionWork,questionCardsView,keepQuestionCard} from './question-bench-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x);
let visit=null;
export function resetQuestionBench(){visit=null;}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,mode:'legacy',screen:'board',slots:new Map(),copies:new Map(),active:null,shelfPage:null,card:null};return visit;}
const button=(attrs,text,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
function art(kind){const drawings={seedlings:'<path d="M31 72V38m0 16Q7 54 11 32q22-2 20 22m0-12q0-25 24-22 2 24-24 22M12 73h42l-6 17H18z"/>',ramps:'<path d="M10 76h70M16 66l50-40v40z"/><circle cx="45" cy="37" r="8"/><path d="m64 81 0 7m-14-7v7m-14-7v7"/>',frogs:'<path d="M20 67Q4 85 14 88m50-21q18 19 6 21M16 66q-3-32 28-32t28 32q-24 24-56 0z"/><circle cx="27" cy="31" r="11"/><circle cx="59" cy="31" r="11"/><path d="M29 60q14 9 28 0"/>',flowers:'<path d="M43 84V43m0 24Q18 43 15 62q5 17 28 12m0-13q25-24 27-3-6 15-27 13"/><circle cx="43" cy="29" r="10"/><path d="M33 23Q17 9 24 6q14-6 19 13Q47 0 57 7q13 8-5 18 22-1 17 12-5 12-19 0-3 22-14 16-12-5-1-17-23 8-22-5 1-13 20-8z"/>',watch:'<path d="M8 46q34-40 68 0-34 40-68 0z"/><circle cx="42" cy="46" r="13"/><path d="M16 77h50m-50 9h38"/>',compare:'<path d="M10 73h66M17 63l20-35v35zm30 0 20-48v48z"/><circle cx="24" cy="42" r="6"/><circle cx="57" cy="27" r="6"/>',research:'<path d="M42 24Q22 12 9 24v53q16-12 33 0 17-12 33 0V24q-15-12-33 0v53M17 34l17 4m-17 9 17 4m17-13 16-4m-16 17 16-4"/>',ask:'<path d="M10 18h63v42H44L26 77V60H10zM22 32h39M22 45h25"/>',card:'<path d="M15 16h54v70H15zM27 34h30M27 48h30M27 62h18"/>'};return `<svg class="qb-art" viewBox="0 0 90 100" aria-hidden="true" focusable="false"><g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${drawings[kind]||drawings.card}</g></svg>`;}
function slot(v){return v.slots.get(v.active)||v.copies.get(v.active);}
function makeSlot(source,work){return {source:clone(source),work:clone(work||newQuestionWork(source)),pending:work?.customQuestion||'',turn:0,inspector:null,glossary:false,status:''};}
function wording(s){return s.work.wording==='own'?s.pending:questionText(s.source,s.work);}
function questionCard(s){return `<section class="qb-paper"><p><strong>${esc(s.source.title)}</strong></p><p class="qb-card-label">${s.work.wording==='own'?'My own words':'Piece-built question'}</p><h2 id="qb-question" tabindex="-1">${esc((wording(s)?.trim().length?wording(s):null)|| (s.work.wording==='own'?'Your question can wait here.':'Choose a detail and a context, or keep these pieces for later.'))}</h2><p>${esc(s.source.wonder)}</p></section>`;}
function sourceHelp(s){return `<details data-qb-glossary${s.glossary?' open':''}><summary>Words and source notes</summary><p>${esc(s.source.origin)}</p><p>${esc(s.source.notice)}</p><dl>${s.source.glossary.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.meaning)}</dd>`).join('')}</dl></details>`;}
function example(s,readonly){return `<section class="qb-example"><h3>An example in parts</h3><p>The fixed example is separate from your draft and may happen to match your choices. It never fills or changes your question for you.</p>${s.source.teaching.slice(0,s.work.exampleSeen).map(t=>`<p>${esc(t)}</p>`).join('')}${readonly?'':button('data-qb-example'+(s.work.exampleSeen>=s.source.teaching.length?' disabled':''),s.work.exampleSeen===0?'An example in parts':s.work.exampleSeen>=s.source.teaching.length?'Example complete':'Next example part')}${!readonly&&s.work.exampleSeen>=s.source.teaching.length?button('data-qb-example-next data-qb-turn="1"','Choose a way'):''}</section>`;}
function methods(s,readonly){const note=s.source.ways.find(w=>w.id===s.inspector);return `<section class="qb-methods"><h3>Choose a way</h3><p>What could this way help you find out? What would it leave unanswered?</p><p>Select any combination, or leave the choices open. Looking up a source and watching can be parts of the same plan. No approach is marked right or wrong.</p><div class="qb-way-grid">${s.source.ways.map(w=>`<article>${art(w.icon)}${readonly?`<p><strong>${esc(w.label)}</strong> · ${s.work.wayIds.includes(w.id)?'selected':'not selected'}</p>`:button(`data-qb-way="${esc(w.id)}" aria-pressed="${s.work.wayIds.includes(w.id)}"`,w.label,s.work.wayIds.includes(w.id))}${button(`data-qb-inspect="${esc(w.id)}" aria-expanded="${s.inspector===w.id}"`,`Read notes: ${w.label}`)}</article>`).join('')}</div><p class="qb-notice">${esc(s.source.methodNotice)}</p>${s.work.wording==='own'?'<p><strong>Notes for the story example.</strong> These notes describe the supplied situation, not an analysis of your wording. With a grown-up, decide what applies to your question.</p>':'<p>A possible plan to discuss, not a result.</p>'}${note?`<section class="qb-method-note"><h3>${esc(note.label)}</h3><h4>What it could help with</h4><p>${esc(note.can)}</p><h4>What it would not establish</h4><p>${esc(note.limit)}</p></section>`:''}</section>`;}
function compose(s){return `<div class="qb-compose">${questionCard(s)}<section class="qb-pieces"><div class="qb-actions" role="group" aria-label="Question wording">${['pieces','own'].map(x=>button(`data-qb-wording="${x}" aria-pressed="${s.work.wording===x}"`,x==='own'?'My own words':'Piece-built question',s.work.wording===x)).join('')}</div>${s.work.wording==='pieces'?[[s.source.focusLabel,s.source.focus,'focus',s.work.focusId],[s.source.contextLabel,s.source.contexts,'context',s.work.contextId]].map(([label,items,kind,value])=>`<fieldset><legend>${esc(label)}</legend>${items.map(x=>button(`data-qb-${kind}="${esc(x.id)}" aria-pressed="${value===x.id}"`,x.label,value===x.id)).join('')}${button(`data-qb-${kind}=""`,'Leave open')}</fieldset>`).join(''):`<label for="qb-own">My question</label><p>You might name what to notice or ask, about which thing, and when or where.</p><textarea id="qb-own" rows="4" aria-describedby="qb-privacy qb-length">${esc(s.pending)}</textarea><p id="qb-length">${questionLength(s.pending)} / 600 characters</p><p id="qb-overlength" role="status">${questionLength(s.pending)>600?'This wording is still here. Shorten it to 600 characters or fewer before keeping the card.':''}</p><p id="qb-privacy">This wording stays in this browser and in any Notes file you download. This app does not upload it for analysis or itself correct or judge it.</p>`}</section></div>`;}
function reflection(s,readonly){return `${readonly?'':button(`data-qb-reflection aria-expanded="${s.work.reflectionShown}"`,'Questions to talk over')}${s.work.reflectionShown?'<section class="qb-reflection"><h3>Questions to talk over</h3><p>What would count as an answer? What would you need to observe, measure, read or ask? What would still be uncertain?</p><p>Your discussion is not graded or recorded.</p></section>':''}`;}
function activePage(s,readonly=false){return `<nav class="qb-turns" aria-label="Question turns">${['Make the question clearer','Choose a way','Keep the question'].map((t,i)=>button(`data-qb-turn="${i}" aria-current="${s.turn===i?'step':'false'}"`,`${i+1}. ${t}`,s.turn===i)).join('')}</nav>${readonly?'<p class="qb-notice">Kept card · this earlier card stays unchanged.</p>':''}${s.turn===0&&!readonly?compose(s):questionCard(s)}${s.turn===1?methods(s,readonly):''}${s.turn===2?`<p>Selected ways: ${esc(s.work.wayIds.map(id=>s.source.ways.find(w=>w.id===id)?.label).join(', ')||'Choices left open')}.</p>${s.work.wording==='own'?`<p>${esc(s.source.methodNotice)}</p>`:''}${reflection(s,readonly)}${readonly?'':button('data-qb-keep','Keep this card',true)}<p>This keeps the exact question, source and choices, not a score. An unfinished question is worth keeping too.</p>`:''}<p id="qb-status" role="status" tabindex="-1">${esc(s.status||'')}</p>${example(s,readonly)}${sourceHelp(s)}`;}
function shelf(v){const view=questionCardsView(v.book),items=view.items,total=items.length;if(v.shelfPage===null){const last=[...items].reverse().find(x=>x.readable);v.shelfPage=Math.floor((last?.index??Math.max(0,total-1))/8);}v.shelfPage=Math.min(v.shelfPage,Math.max(0,Math.ceil(total/8)-1));const start=v.shelfPage*8;return `<h2 id="qb-question" tabindex="-1">Kept cards</h2><p>Copies of questions and choices, not scores.</p>${view.status==='unavailable'?'<p>This saved format cannot accept another card here. Its original is retained in your Notes download; you can still explore a draft.</p>':''}${!total?'<p>You can keep an unfinished thought too.</p>':`<p>Cards ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol class="qb-shelf" start="${start+1}">${items.slice(start,start+8).map(x=>`<li>${x.readable?button(`data-qb-card="${esc(x.id)}"`,`Card ${x.index+1} · ${x.raw.source.title}`):'<p>This earlier card cannot be opened here. Its original stays unchanged in your Notes download. Other cards remain open.</p>'}</li>`).join('')}</ol><div class="qb-actions">${button('data-qb-page="-1"'+(start===0?' disabled':''),'Previous cards')}${button('data-qb-page="1"'+(start+8>=total?' disabled':''),'Next cards')}</div>${!items.some(x=>x.readable)?'<p>Earlier saved data stays in your Notes download. None of these cards can be opened here, but new drafts remain open.</p>':''}`}`;}
export function questionBenchPage(book,owner){const v=state(book,owner);if(v.mode==='legacy')return `<div data-qb-host>${button('data-qb-enter','Question Bench')}${fairTestPage(book)}</div>`;let body;if(v.screen==='board')body=`<h2 id="qb-question" tabindex="-1">Choose a wonder</h2><p>You can return to each draft while you stay here.</p><div class="qb-board">${questionCases.map(c=>`<button type="button" class="qb-slip" data-qb-case="${esc(c.id)}">${art(c.id)}<strong>${esc(c.title)}</strong><span>${esc(c.wonder)}</span></button>`).join('')}</div>`;else if(v.screen==='shelf')body=shelf(v);else if(v.screen==='card'){const x=questionCardsView(book).items.find(i=>i.id===v.card&&i.readable);if(x){v.readonly ||= new Map();if(!v.readonly.has(x.id))v.readonly.set(x.id,makeSlot(x.raw.source,x.raw.work));body=activePage(v.readonly.get(x.id),true)+button('data-qb-copy',v.copies.has(x.id)?'Return to your copy':'Work on a copy');}else body='<h2 id="qb-question" tabindex="-1">This earlier card cannot be opened here.</h2><p>Its original stays unchanged in your Notes download. Other cards remain open.</p>';}else body=activePage(slot(v));return `<div class="qb-page" data-qb-root><header><div class="qb-actions">${button('data-qb-legacy','Back to Fair Test')}${button('data-qb-board','Other wonders')}${button('data-qb-shelf','Kept cards')}${button('data-qb-hear data-speak=""','Hear this page')}</div><h1>Question Bench</h1><p>The town has new wonders. Make a question someone could investigate.</p><p class="qb-notice"><strong>A story plan, not a result.</strong> Nothing here runs an experiment or collects new observations. Different questions need different kinds of evidence. More than one approach can help.</p></header>${body}<p class="qb-visit-note">Leaving or reloading loses drafts that have not been kept.</p></div>`;}
function visibleSpeech(root){function read(node){if(node.nodeType===3)return node.textContent+' ';if(node.nodeType!==1)return '';if(node.matches('button,input,textarea,select,svg,[aria-hidden="true"],[hidden],.speech-controls'))return '';if(node.tagName==='DETAILS'&&!node.open)return '';return [...node.childNodes].map(read).join(' ');}return read(root).replace(/\s+/g,' ').trim();}
export function bindQuestionBench(book,ctx){const owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId;const v=state(book,owner),root=document.querySelector(v.mode==='legacy'?'[data-qb-host]':'[data-qb-root]');if(!root)return;const mode=v.mode,screen=v.screen,active=v.active,card=v.card;const currentSlot=()=>v.screen==='card'?v.readonly?.get(v.card):slot(v);const held=currentSlot(),heldSource=held?.source,savedSource=screen==='card'?questionCardsView(book).items.find(x=>x.id===card&&x.readable)?.raw.source:null;const contentLive=()=>currentSlot()===held&&held?.source===heldSource&&(screen!=='card'||questionCardsView(book).items.some(x=>x.id===card&&x.readable&&x.raw.source===savedSource));const contentNode=node=>mode!=='legacy'&&node.matches('[data-qb-turn],[data-qb-copy],[data-qb-wording],[data-qb-focus],[data-qb-context],[data-qb-way],[data-qb-inspect],[data-qb-example],[data-qb-reflection],[data-qb-keep],#qb-own,[data-qb-glossary],[data-qb-hear]');const live=node=>visit===v&&v.book===book&&v.owner===(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook)===book&&ctx.isActive()&&window.location.hash==='#workshop/fair'&&root.isConnected&&node.isConnected&&v.mode===mode&&v.screen===screen&&v.active===active&&v.card===card&&(!contentNode(node)||contentLive());const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};const redraw=(target='#qb-question')=>{ctx.render();ctx.focus(target);};const guard=node=>{for(const type of ['click','change','input','toggle'])node.addEventListener(type,e=>{if(!live(node)){e.stopImmediatePropagation();e.preventDefault();}},{capture:true});};guard(root);root.querySelectorAll('button,select,input,textarea,details,[data-speak]').forEach(guard);const on=(selector,fn)=>root.querySelectorAll(selector).forEach(node=>node.addEventListener('click',()=>{if(!live(node)||node.disabled)return;stop();fn(node);}));if(mode==='legacy'){on('[data-qb-enter]',()=>{v.mode='bench';redraw();});bindFairTest(book,{save:ctx.save,render:ctx.render,focus:ctx.focus});return;}
const current=()=>v.screen==='card'?v.readonly?.get(v.card):slot(v);const update=(action,value)=>{const s=current();if(!s||!contentLive())return false;const next=changeQuestionWork(s.source,s.work,action,value);if(!next)return false;s.work=next;s.status='';return true;};const helpRedraw=selector=>redraw(selector);const attr=(key,value)=>`[${key}="${CSS.escape(value)}"]`;
on('[data-qb-legacy]',()=>{v.mode='legacy';ctx.render();ctx.focus('[data-qb-enter]');});on('[data-qb-board]',()=>{v.screen='board';redraw();});on('[data-qb-shelf]',()=>{v.screen='shelf';redraw();});on('[data-qb-case]',n=>{if(!v.slots.has(n.dataset.qbCase))v.slots.set(n.dataset.qbCase,makeSlot(questionSource(n.dataset.qbCase)));v.active=n.dataset.qbCase;v.screen='draft';redraw();});on('[data-qb-turn]',n=>{current().turn=Number(n.dataset.qbTurn);redraw();});on('[data-qb-page]',n=>{v.shelfPage+=Number(n.dataset.qbPage);redraw();});on('[data-qb-card]',n=>{v.card=n.dataset.qbCard;v.screen='card';redraw();});on('[data-qb-copy]',()=>{const x=questionCardsView(book).items.find(i=>i.id===v.card&&i.readable);if(!x)return;if(!v.copies.has(v.card))v.copies.set(v.card,makeSlot(x.raw.source,x.raw.work));v.active=v.card;v.screen='draft';redraw();});
if(screen==='draft'){on('[data-qb-wording]',n=>{update('wording',n.dataset.qbWording);helpRedraw(attr('data-qb-wording',n.dataset.qbWording));});for(const kind of ['focus','context'])on(`[data-qb-${kind}]`,n=>{const value=n.dataset[kind==='focus'?'qbFocus':'qbContext'];update(kind,value||null);helpRedraw(attr(`data-qb-${kind}`,value));});on('[data-qb-way]',n=>{update('way',n.dataset.qbWay);current().inspector=n.dataset.qbWay;helpRedraw(attr('data-qb-way',n.dataset.qbWay));});on('[data-qb-example]',()=>{update('example');const s=current();helpRedraw(s.work.exampleSeen>=s.source.teaching.length?'[data-qb-example-next]':'[data-qb-example]');});on('[data-qb-reflection]',()=>{update('reflection');helpRedraw('[data-qb-reflection]');});const field=root.querySelector('#qb-own');field?.addEventListener('input',()=>{if(!live(field))return;stop();const s=current();s.pending=field.value;const length=questionLength(s.pending);if(length<=600){update('question',s.pending);root.querySelector('#qb-status').textContent=s.status;}root.querySelector('#qb-length').textContent=`${length} / 600 characters`;root.querySelector('#qb-overlength').textContent=length>600?'This wording is still here. Shorten it to 600 characters or fewer before keeping the card.':'';root.querySelector('#qb-question').textContent=s.pending.trim().length?s.pending:'Your question can wait here.';});on('[data-qb-keep]',()=>{const s=current();if(questionLength(s.pending)>600){s.status='This wording is still here. Shorten it to 600 characters or fewer before keeping the card.';redraw('#qb-status');return;}const id=keepQuestionCard(book,s.source,s.work,{canExport:ctx.canExport});if(!id){const view=questionCardsView(book);s.status=view.status==='unavailable'?'This saved format cannot accept another card here. Its original is retained in your Notes download; you can still explore a draft.':!view.canKeep?'No new card number is available here. Earlier cards stay unchanged; this draft can still be explored and discussed.':'This card has not been kept. Your earlier cards stay unchanged in the Notes download. This draft is still here for this visit; you can discuss it or return to it before leaving.';}else{const saved=ctx.save();s.status=saved?.enabled===false?'This card is kept in this open page, but saving is off. Download Grown-up notes before closing if you want to bring it back.':saved?.ok===false?'This card is kept in this open page, but device storage did not save. Download Grown-up notes before closing if you want to bring it back.':'This card is kept. You can find it in Kept cards.';v.shelfPage=null;v.readonly ||= new Map();const kept=makeSlot(s.source,s.work);kept.turn=2;kept.status=s.status;v.readonly.set(id,kept);v.card=id;v.screen='card';}redraw('#qb-status');});}
on('[data-qb-inspect]',n=>{current().inspector=current().inspector===n.dataset.qbInspect?null:n.dataset.qbInspect;helpRedraw(attr('data-qb-inspect',n.dataset.qbInspect));});const glossary=root.querySelector('[data-qb-glossary]');glossary?.addEventListener('toggle',()=>{if(live(glossary)){stop();current().glossary=glossary.open;}});const hear=root.querySelector('[data-qb-hear]');hear?.addEventListener('click',()=>{if(live(hear))hear.dataset.speak=visibleSpeech(root);},{capture:true});
}
